/// <summary>
/// SalesQuotationTable_OnActivated
/// </summary>
/// <param name = "sender">SalesQuotationTableDS</param>
/// <param name = "e">FormDataSourceEventArgs</param>
[   SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataSourceEventHandler(formDataSourceStr(SalesQuotationListPage, SalesQuotationTable), FormDataSourceEventType::Activated)]
public static void SalesQuotationTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    SalesQuotationTable                     salesQuotationTable;
    KCS_HDMSalesQuotationTableInfoFields    infoFields;
    FormRun                                 formRun;
    FormButtonControl                       button;

    FormDataSource dataSource   = sender.formRun().dataSource(formDataSourceStr (SalesQuotationListPage, SalesQuotationTable));
    salesQuotationTable         = dataSource.cursor() as SalesQuotationTable;
    infoFields                  = KCS_HDMSalesQuotationTableInfoFields::find(salesQuotationTable.QuotationId);
    formRun                     = sender.formRun();
    button = formRun.design().controlName(formControlStr(SalesQuotationListPage, AVASQInfoFields)) as FormButtonControl;
    if (infoFields.InfoField1 || infoFields.InfoField2 || infoFields.InfoField3 || infoFields.InfoField4)
    {
        //button.toggleButton(ToggleButtonStyle::Check);
        //button.toggleValue(OnOff::On);
        button.text("@NDX:NDAInfoExists");
    } 
    else
    {
        //button.toggleButton(ToggleButtonStyle::None);
        //button.toggleValue(OnOff::Off);
        button.text("@NDX:NDANoInfoExists");
    }

    sender.formRun().design().controlName('AVAQuotExcel').enabled(salesQuotationTable.lastQuotation() != '');
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name="sender">FormDataSource</param>
/// <param name="e">FormDataSourceEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataSourceEventHandler(formDataSourceStr(SalesQuotationTable, SalesQuotationTable), FormDataSourceEventType::Created)]
public static void SalesQuotationTable_OnCreated(FormDataSource sender, FormDataSourceEventArgs e)
{
    DirPartyRecId       party;

    SalesQuotationTable salesQuotationTable = sender.cursor() as salesQuotationTable;
    if (salesQuotationTable.CustAccount)
    {
        party = CustTable::find(salesQuotationTable.CustAccount).Party;
    }
    else if (salesQuotationTable.BusRelAccount)
    {
        party = smmBusRelTable::find(salesQuotationTable.BusRelAccount).Party;
    }

    if (party)
    {
        KCS_HDMSalesQuotationTableInfoFields::initInfoFields(party, salesQuotationTable.QuotationId);
    }
}

/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "sender">FormDataSource</param>
/// <param name = "e">FormDataSourceEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormDataSourceEventHandler(formDataSourceStr(SalesQuotationListPage, SalesQuotationTable), FormDataSourceEventType::DisplayOptionInitialize)]
public static void SalesQuotationTable_OnDisplayOptionInitialize(FormDataSource sender, FormDataSourceEventArgs e)
{
    FormDataSourceDisplayOptionInitializeEventArgs  event = e as FormDataSourceDisplayOptionInitializeEventArgs;
    SalesQuotationTable             salesQuotationTable = event.record();
    KCS_QuotationStatus             quotationStatus;
    int                             textColor;

    select firstonly KCS_Color from quotationStatus where quotationStatus.KCS_StatusId == salesQuotationTable.KCS_StatusId;
    textColor = WinAPI::RGB2int( 0,0,0 );
    switch(quotationStatus.KCS_Color)
    {
        case SysColor::White:
            textColor = WinAPI::RGB2int( 0,0,0 );
            break;
        case SysColor::Blue:
            textColor = WinAPI::RGB2int( 0,0,255 );
            break;
        case SysColor::Aqua:
            textColor = WinAPI::RGB2int( 0,255,255 );
            break;
        case SysColor::Black:
            textColor = WinAPI::RGB2int( 0,0,0 );
            break;
        case SysColor::Fuchsia:
            textColor = WinAPI::RGB2int( 255,0,255 );
            break;
        case SysColor::Gray:
            textColor = WinAPI::RGB2int( 128,128,128 );
            break;
        case SysColor::Green:
            textColor = WinAPI::RGB2int( 0,128,0 );
            break;
        case SysColor::Lime:
            textColor = WinAPI::RGB2int( 0,255,0 );
            break;
        case SysColor::Maroon:
            textColor = WinAPI::RGB2int( 128,0,0 );
            break;
        case SysColor::Navy:
            textColor = WinAPI::RGB2int( 0,0,128 );
            break;
        case SysColor::Olive:
            textColor = WinAPI::RGB2int( 128,128,0 );
            break;
        case SysColor::Purple:
            textColor = WinAPI::RGB2int( 128,0,128 );
            break;
        case SysColor::Red:
            textColor = WinAPI::RGB2int( 255,0,0 );
            break;
        case SysColor::Silver:
            textColor = WinAPI::RGB2int( 192,192,192 );
            break;
        case SysColor::Teal:
            textColor = WinAPI::RGB2int( 0,128,128 );
            break;
        case SysColor::Yellow:
            textColor = WinAPI::RGB2int( 255,255,0 );
            break;
    }
    event.displayOption().textColor(textColor);
}
